<script>
  // Mega menu toggle
  function toggleMegaMenu() {
    const item = document.getElementById('servicesNavItem');
    const btn = document.getElementById('servicesBtn');
    const isOpen = item.classList.toggle('open');
    btn.setAttribute('aria-expanded', isOpen);
  }
  // Close mega menu on outside click
  document.addEventListener('click', function(e) {
    const item = document.getElementById('servicesNavItem');
    if (!item.contains(e.target)) {
      item.classList.remove('open');
      document.getElementById('servicesBtn').setAttribute('aria-expanded', 'false');
    }
  });

  // Mobile nav
  function toggleMobile() {
    const nav = document.getElementById('mobileNav');
    const btn = document.getElementById('hamburger');
    const isOpen = nav.classList.toggle('open');
    btn.setAttribute('aria-expanded', isOpen);
  }
  function toggleMobileSub(trigger) {
    const sub = trigger.nextElementSibling;
    const isOpen = sub.classList.toggle('open');
    trigger.classList.toggle('open', isOpen);
  }

  // What We Do tabs
  function switchTab(id) {
    document.querySelectorAll('.wwd-tab').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-selected', 'false');
    });
    document.querySelectorAll('.wwd-panel').forEach(p => p.classList.remove('active'));
    const tab = document.getElementById('tab-' + id);
    const panel = document.getElementById('panel-' + id);
    tab.classList.add('active');
    tab.setAttribute('aria-selected', 'true');
    panel.classList.add('active');
  }

  // Newsletter submit
  function handleSubscribe(e) {
    e.preventDefault();
    const btn = e.target.querySelector('button');
    btn.textContent = 'Subscribed!';
    btn.style.background = '#003F2D';
    setTimeout(() => { btn.textContent = 'Subscribe'; btn.style.background = ''; }, 3000);
  }
</script>
