    .insight-date{font-size:0.8125rem;color:var(--gray-400);}

    /* FOOTER */
    .site-footer{background:var(--navy);}
    .footer-main{max-width:1200px;margin:0 auto;padding:64px 40px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:48px;}
