    .footer-col-title{font-size:0.7rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:var(--gold);margin-bottom:16px;}
    .footer-link{display:block;color:rgba(255,255,255,0.65);font-size:0.875rem;padding:4px 0;transition:color var(--transition);}
    .footer-link:hover{color:var(--white);}
    .footer-bottom{border-top:1px solid rgba(255,255,255,0.08);}
    .footer-bottom-inner{max-width:1200px;margin:0 auto;padding:20px 40px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap;}
    .footer-legal{font-size:0.8125rem;color:rgba(255,255,255,0.4);}
    .footer-legal-links{display:flex;gap:20px;flex-wrap:wrap;}
    .footer-legal-link{font-size:0.8125rem;color:rgba(255,255,255,0.5);transition:color var(--transition);}
    .footer-legal-link:hover{color:var(--white);}

    @media(max-width:1024px){.main-nav{display:none;}.header-cta{display:none;}.hamburger{display:flex;}.cap-grid{grid-template-columns:repeat(2,1fr);}.topics-grid{grid-template-columns:repeat(2,1fr);}.related-grid{grid-template-columns:1fr;}.insights-grid{grid-template-columns:repeat(2,1fr);}.footer-main{grid-template-columns:1fr 1fr;}.partner-card{flex:0 0 calc(50% - 12px);}}
    @media(max-width:768px){.header-top{padding:0 20px;}.page-hero,.section-pad,.capabilities-section,.partners-section,.deal-cta,.testimonial-section,.topics-section,.prop-types,.related-section,.insights-section{padding-left:20px;padding-right:20px;}.cap-grid{grid-template-columns:1fr;}.topics-grid{grid-template-columns:1fr 1fr;}.insights-grid{grid-template-columns:1fr;}.footer-main{grid-template-columns:1fr;gap:32px;padding:40px 20px;}.footer-bottom-inner{padding:16px 20px;flex-direction:column;align-items:flex-start;}.partner-card{flex:0 0 calc(100%);}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{transition-duration:0ms!important;animation-duration:0ms!important;}}
  </style>
</head>
